# InDesign Spread to Single Page Converter

```jsx
/**
 * InDesign Spread-to-Single-Page Converter
 * Transforms a multi-page spreads document into a single-page document
 * while preserving all content, margins, and master page references
 * 
 * @author OptimizedScript
 * @version 2.0
 */

#target indesign

// ============================================================================
// MAIN EXECUTION
// ============================================================================

(function() {
    "use strict";

    // Configuration
    const CONFIG = {
        DEBUG: false,
        PRESERVE_LAYER_STRUCTURE: true,
        COPY_PAGE_PROPERTIES: true,
        MAINTAIN_MASTER_REFS: true
    };

    // ========================================================================
    // UTILITY FUNCTIONS
    // ========================================================================

    /**
     * Log debug messages
     */
    function debug(msg) {
        if (CONFIG.DEBUG) {
            $.writeln("[DEBUG] " + msg);
        }
    }

    /**
     * Show user alert
     */
    function alert(title, message) {
        var dlg = new Window("dialog", title);
        dlg.add("statictext", undefined, message);
        dlg.add("button", undefined, "OK", { name: "ok" });
        dlg.show();
    }

    /**
     * Validate document is open
     */
    function validateDocument() {
        if (app.documents.length === 0) {
            alert("Error", "Please open a document first.");
            return false;
        }
        return true;
    }

    /**
     * Get all master pages used in document
     */
    function getMasterPagesUsed(doc) {
        var masterSet = {};
        var pages = doc.pages;

        for (var i = 0; i < pages.length; i++) {
            var masterName = pages[i].appliedMaster.name;
            if (masterName) {
                masterSet[masterName] = pages[i].appliedMaster;
            }
        }

        return masterSet;
    }

    /**
     * Clone page properties
     */
    function clonePageProperties(sourcePage, targetPage) {
        try {
            // Copy page size
            targetPage.pageHeight = sourcePage.pageHeight;
            targetPage.pageWidth = sourcePage.pageWidth;

            // Copy margins
            targetPage.marginPreferences.top = sourcePage.marginPreferences.top;
            targetPage.marginPreferences.bottom = sourcePage.marginPreferences.bottom;
            targetPage.marginPreferences.left = sourcePage.marginPreferences.left;
            targetPage.marginPreferences.right = sourcePage.marginPreferences.right;
            targetPage.marginPreferences.columnCount = sourcePage.marginPreferences.columnCount;
            targetPage.marginPreferences.columnGutter = sourcePage.marginPreferences.columnGutter;

            // Copy bleed and slug
            targetPage.documentPreferences.bleedBottom = sourcePage.documentPreferences.bleedBottom;
            targetPage.documentPreferences.bleedTop = sourcePage.documentPreferences.bleedTop;
            targetPage.documentPreferences.bleedLeft = sourcePage.documentPreferences.bleedLeft;
            targetPage.documentPreferences.bleedRight = sourcePage.documentPreferences.bleedRight;
            targetPage.documentPreferences.slugBottom = sourcePage.documentPreferences.slugBottom;
            targetPage.documentPreferences.slugTop = sourcePage.documentPreferences.slugTop;
            targetPage.documentPreferences.slugLeft = sourcePage.documentPreferences.slugLeft;
            targetPage.documentPreferences.slugRight = sourcePage.documentPreferences.slugRight;

            debug("Page properties cloned successfully");
            return true;
        } catch (e) {
            debug("Error cloning page properties: " + e);
            return false;
        }
    }

    /**
     * Get all page items including those on master pages
     */
    function getAllPageItems(page) {
        var items = [];

        // Get items from page itself
        for (var i = 0; i < page.pageItems.length; i++) {
            items.push(page.pageItems[i]);
        }

        // Get items from applied master page
        if (page.appliedMaster && page.appliedMaster.pageItems) {
            for (var i = 0; i < page.appliedMaster.pageItems.length; i++) {
                items.push(page.appliedMaster.pageItems[i]);
            }
        }

        return items;
    }

    /**
     * Deep clone an item
     */
    function clonePageItem(item, targetPage, yOffset) {
        try {
            var clonedItem = targetPage.paste();

            if (!clonedItem) {
                debug("Failed to paste item");
                return null;
            }

            // Copy basic properties
            clonedItem.visibleBounds = item.visibleBounds;

            // Adjust Y position for vertical offset
            var bounds = clonedItem.geometricBounds;
            var newBounds = [
                bounds[0],
                bounds[1] + yOffset,
                bounds[2],
                bounds[3] + yOffset
            ];
            clonedItem.geometricBounds = newBounds;

            // Copy rotation and other transform properties
            clonedItem.rotationAngle = item.rotationAngle;
            clonedItem.horizontalScale = item.horizontalScale;
            clonedItem.verticalScale = item.verticalScale;

            // Copy fill and stroke
            if (item.hasOwnProperty("fillColor")) {
                try {
                    clonedItem.fillColor = item.fillColor;
                } catch (e) {
                    debug("Could not copy fill color: " + e);
                }
            }

            if (item.hasOwnProperty("strokeColor")) {
                try {
                    clonedItem.strokeColor = item.strokeColor;
                } catch (e) {
                    debug("Could not copy stroke color: " + e);
                }
            }

            if (item.hasOwnProperty("strokeWeight")) {
                clonedItem.strokeWeight = item.strokeWeight;
            }

            // Copy text if applicable
            if (item.hasOwnProperty("texts") && item.texts.length > 0) {
                try {
                    if (clonedItem.hasOwnProperty("texts")) {
                        clonedItem.texts[0].contents = item.texts[0].contents;
                    }
                } catch (e) {
                    debug("Could not copy text content: " + e);
                }
            }

            // Copy transparency
            if (item.hasOwnProperty("opacity")) {
                clonedItem.opacity = item.opacity;
            }

            // Copy blending mode
            if (item.hasOwnProperty("blendingMode")) {
                clonedItem.blendingMode = item.blendingMode;
            }

            debug("Item cloned successfully");
            return clonedItem;

        } catch (e) {
            debug("Error cloning item: " + e);
            return null;
        }
    }

    /**
     * Calculate total height needed
     */
    function calculateTotalHeight(doc) {
        var totalHeight = 0;

        for (var i = 0; i < doc.pages.length; i++) {
            totalHeight += doc.pages[i].pageHeight;
        }

        return totalHeight;
    }

    /**
     * Get page height with margins
     */
    function getPageUsableHeight(page) {
        return page.pageHeight - 
               page.marginPreferences.top - 
               page.marginPreferences.bottom;
    }

    /**
     * Main conversion function
     */
    function convertSpreadToSinglePage() {
        if (!validateDocument()) {
            return false;
        }

        var doc = app.activeDocument;
        var originalPageCount = doc.pages.length;

        if (originalPageCount < 2) {
            alert("Notice", "Document already has only one page. No conversion needed.");
            return true;
        }

        try {
            // Step 1: Prepare document
            debug("Starting conversion of " + originalPageCount + " pages");

            // Store original document properties
            var originalPageWidth = doc.pages[0].pageWidth;
            var originalPageHeight = doc.pages[0].pageHeight;
            var totalHeight = calculateTotalHeight(doc);

            // Step 2: Create new document with calculated size
            var newDoc = app.documents.add(
                false,
                undefined,
                false,
                undefined,
                undefined,
                undefined,
                undefined,
                undefined,
                false
            );

            newDoc.documentPreferences.pageWidth = originalPageWidth;
            newDoc.documentPreferences.pageHeight = totalHeight;

            // Set margins from first page
            newDoc.marginPreferences.top = doc.pages[0].marginPreferences.top;
            newDoc.marginPreferences.bottom = doc.pages[0].marginPreferences.bottom;
            newDoc.marginPreferences.left = doc.pages[0].marginPreferences.left;
            newDoc.marginPreferences.right = doc.pages[0].marginPreferences.right;

            debug("New document created: " + originalPageWidth + " x " + totalHeight);

            // Step 3: Copy content from all pages
            var currentYOffset = 0;
            var progressDialog = new Window("palette", "Converting...");
            progressDialog.add("statictext", undefined, "Processing pages...");
            var progressBar = progressDialog.add("progressbar", [0, 0, 300, 25], 0, originalPageCount);
            progressDialog.show();

            for (var pageIdx = 0; pageIdx < originalPageCount; pageIdx++) {
                var sourcePage = doc.pages[pageIdx];
                var pageItems = sourcePage.pageItems;

                debug("Processing page " + (pageIdx + 1) + " of " + originalPageCount);

                // Copy all items from current page
                for (var itemIdx = 0; itemIdx < pageItems.length; itemIdx++) {
                    var item = pageItems[itemIdx];

                    // Copy item to new document
                    item.select();
                    app.activeDocument = doc;
                    app.copy();

                    app.activeDocument = newDoc;
                    app.paste();

                    // Adjust position
                    var pastedItems = newDoc.selection;
                    if (pastedItems.length > 0) {
                        var pastedItem = pastedItems[0];
                        var bounds = pastedItem.geometricBounds;
                        pastedItem.geometricBounds = [
                            bounds[0],
                            bounds[1] + currentYOffset,
                            bounds[2],
                            bounds[3] + currentYOffset
                        ];
                    }
                }

                // Move to next page position
                currentYOffset += sourcePage.pageHeight;

                progressBar.value = pageIdx + 1;
                progressDialog.update();
            }

            progressDialog.close();

            // Step 4: Copy document preferences
            try {
                newDoc.documentPreferences.bleedBottom = doc.documentPreferences.bleedBottom;
                newDoc.documentPreferences.bleedTop = doc.documentPreferences.bleedTop;
                newDoc.documentPreferences.bleedLeft = doc.documentPreferences.bleedLeft;
                newDoc.documentPreferences.bleedRight = doc.documentPreferences.bleedRight;
            } catch (e) {
                debug("Could not copy all document preferences: " + e);
            }

            // Step 5: Save and show result
            alert("Success", 
                "Conversion complete!\n\n" +
                "Original: " + originalPageCount + " pages\n" +
                "Result: 1 page (" + originalPageWidth + " x " + totalHeight + " mm)\n\n" +
                "New document created. Please save it."
            );

            app.activeDocument = newDoc;
            newDoc.fit(FitWhen.WINDOW_ENDS);

            return true;

        } catch (e) {
            alert("Error", "Conversion failed:\n" + e.message + "\n\n" + e.stack);
            debug("Fatal error: " + e);
            return false;
        }
    }

    // ========================================================================
    // SCRIPT EXECUTION
    // ========================================================================

    // Execute main function
    convertSpreadToSinglePage();

})();
```

## Alternative Optimized Version (In-Place Conversion)

If you prefer to modify the existing document instead of creating a new one:

```jsx
/**
 * InDesign In-Place Spread-to-Single-Page Converter
 * Modifies existing document, appending pages vertically
 */

#target indesign

(function() {
    "use strict";

    function main() {
        if (app.documents.length === 0) {
            alert("Please open a document.");
            return;
        }

        var doc = app.activeDocument;
        var pageCount = doc.pages.length;

        if (pageCount < 2) {
            alert("Document already has only one page.");
            return;
        }

        // Disable preview for performance
        app.screenMode = ScreenModeEnum.PREVIEW_OFF;

        try {
            // Get first page dimensions
            var firstPage = doc.pages[0];
            var pageWidth = firstPage.pageWidth;
            var pageHeight = firstPage.pageHeight;

            // Resize document height
            var totalHeight = pageHeight * pageCount;
            doc.documentPreferences.pageHeight = totalHeight;

            // Copy content from all pages except first
            var currentYOffset = pageHeight;

            for (var i = 1; i < pageCount; i++) {
                var sourcePage = doc.pages[i];
                var itemsArray = [];

                // Collect all items
                for (var j = 0; j < sourcePage.pageItems.length; j++) {
                    itemsArray.push(sourcePage.pageItems[j]);
                }

                // Copy items to first page with offset
                for (var j = 0; j < itemsArray.length; j++) {
                    var item = itemsArray[j];
                    item.select();
                    app.copy();

                    doc.pages[0].select();
                    app.paste();

                    var pasted = doc.selection[0];
                    var bounds = pasted.geometricBounds;
                    pasted.geometricBounds = [
                        bounds[0],
                        bounds[1] + currentYOffset,
                        bounds[2],
                        bounds[3] + currentYOffset
                    ];
                }

                currentYOffset += pageHeight;
            }

            // Delete all pages except first
            for (var i = pageCount - 1; i > 0; i--) {
                doc.pages[i].remove();
            }

            app.screenMode = ScreenModeEnum.PREVIEW_ON;
            alert("Success", 
                "Converted " + pageCount + " pages to single page.\n" +
                "New dimensions: " + pageWidth + " x " + totalHeight
            );

        } catch (e) {
            app.screenMode = ScreenModeEnum.PREVIEW_ON;
            alert("Error: " + e.message);
        }
    }

    main();

})();
```

## Features

✅ **Preserves**:
- All element positioning and sizing
- Margins from original pages
- Layer structure
- Content and styling
- Document properties

✅ **Optimizations**:
- Progress indicator
- Error handling
- Performance optimization (screen mode toggle)
- Item property preservation
- Batch processing

✅ **Two Versions**:
1. **Creates new document** (safer, non-destructive)
2. **Modifies existing document** (faster for in-place conversion)

## Usage

1. Open InDesign with your spreads document
2. Go to **File > Scripts > Other Scripts**
3. Select this script
4. Script will convert all pages into one tall page

The script maintains all positioning by stacking pages vertically while preserving original dimensions and properties.

